#!/usr/bin/env node
// Regenerates src/esi/systemData.json from CCP's official Static Data Export (SDE).
//
// Solar system names are effectively static and are needed for Signature Tracker's option-locked
// autocomplete. So instead of resolving names through ESI at runtime, Evelyn bundles a trimmed
// dataset generated by this script.

import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { downloadSdeZip, extractYamlFile, isMainModule } from "./sde.mjs";

const OUTPUT_PATH = fileURLToPath(new URL("../src/esi/systemData.json", import.meta.url));

function resolveName(record) {
  const candidate =
    record.name?.en ?? record.solarSystemNameID ?? record.solarSystemName ?? record.name;
  return typeof candidate === "string" ? candidate : candidate?.en;
}

export async function generate(zipBuffer) {
  // CCP dropped the `fsd/` directory prefix in a later SDE rework, so the current layout has
  // this file at the zip root; the prefixed path is kept as a fallback for older zips.
  const systems = extractYamlFile(zipBuffer, ["mapSolarSystems.yaml", "fsd/mapSolarSystems.yaml"]);

  const data = [];
  for (const [systemIdStr, system] of Object.entries(systems)) {
    if (system.deleted) continue;

    const name = resolveName(system);
    if (!name) continue;

    data.push({ systemId: Number(systemIdStr), name });
  }

  data.sort((a, b) => a.name.localeCompare(b.name));
  await writeFile(OUTPUT_PATH, JSON.stringify(data));

  console.log(`Wrote ${data.length} solar systems to ${OUTPUT_PATH}`);
}

async function main() {
  await generate(await downloadSdeZip());
}

if (isMainModule(import.meta.url)) {
  main().catch((err) => {
    console.error(err);
    process.exitCode = 1;
  });
}
